            return False
    def open_file(self):
        close_file = False
        f = self.file
        if f.closed:
            if self.is_stored_locally():
                f.open("rb")
            else:
                storage = self._meta.get_field("file").storage
                f = storage.open(f.name, "rb")
            close_file = True
        f.seek(0)
        try:
            yield f
        finally:
            if close_file:
                f.close()
