        if hasattr(ob, "canDownload"):
            if not ob.canDownload():
                return HttpResponseNotFound()
    for ob in images:
        well = None
        try:
            well = ob.getParent().getParent()
        except Exception:
            if hasattr(ob, "canDownload"):
                if not ob.canDownload():
                    return HttpResponseNotFound()
