            Path(hit["data"]["path"]["text"]).parts[-1].replace(".md", "").split("-")
        )
        curr_id = int(curr_file[0])
        title = curr_file[-1].replace("_", " ")
        data = {"title": title, "matches": [], "id": curr_id}
