        var = templates_vars.get(var_name, None)
        if var is None:
            raise ExecutionError(f"Variable \"{var_name}\" does not exist.")
        sequences = var.split(params.separator, maxsplit=params.max_split)
        for i, var in enumerate(params.split_into):
            try:
                templates_vars[var] = sequences[i]
            except IndexError:
                templates_vars[var] = ""
    @processor(Action.VarTransform)
    async def var_transform(params: models.VarTransform):
        var_name = safe_sub(params.var_name)
        var = templates_vars.get(var_name, None)
        if var is None:
            raise ExecutionError(f"Variable \"{var_name}\" does not exist.")
        operation = params.operation.lower()
        if operation == "capitalize":
            var = var.capitalize()
        elif operation == "lowercase":
            var = var.lower()
        elif operation == "reverse":
            var = var[::-1]
        elif operation == "uppercase":
            var = var.upper()
        elif operation == "title":
            var = var.title()
        templates_vars[var_name] = var
    @processor(Action.VarSlice)
    async def var_slice(params: models.VarSlice):
        var_name = safe_sub(params.var_name)
        var = templates_vars.get(var_name, None)
        if var is None:
            raise ExecutionError(f"Variable \"{var_name}\" does not exist.")
        var = var[params.index:params.end_index:params.step]
        if params.slice_into:
            templates_vars[safe_sub(params.slice_into)] = var
        else:
            templates_vars[var_name] = var
    @processor(Action.NoOp)
    async def no_op(params: models.IsNone):
        pass
    if debug:
        for action in Action:
            if action not in processors:
                raise ExecutionError(f"{action.value} does not have a processor.")
    async def process_action(action, value):
        self.last_action = action
        if debug and action not in ALLOWED_DEBUG_ACTIONS:
            return
        params = model_validator(action, value)
        try:
            processor_func = processors[action]
        except KeyError:
            raise ExecutionError(f"Unhandled action '{action.value}'.")
        await processor_func(params)
    last_cond_action_result = None
    for entry in self.actions:
        for enum, value in entry.items():
            enum = self._get_actions_enum(enum)
            if isinstance(enum, Action):
                try:
                    await process_action(enum, value)
                except StopExecution:
                    return bool(last_expel_action)
            elif isinstance(enum, Condition):
                _eval = await self._evaluate_conditions([{enum.value: value}],
                                                        cog=cog, user=user, message=message,
                                                        guild=guild, templates_vars=templates_vars,
                                                        debug=debug)
                last_cond_action_result = _eval[0]
            elif isinstance(enum, ConditionBlock):
                _eval = await self._evaluate_conditions_block(block=[{enum.value: value}],
                                                              cog=cog, user=user, message=message,
                                                              guild=guild, templates_vars=templates_vars,
                                                              debug=debug)
                last_cond_action_result = bool(_eval)
            elif isinstance(enum, ConditionalActionBlock):
                is_true = enum == ConditionalActionBlock.IfTrue and last_cond_action_result is True
                is_false = enum == ConditionalActionBlock.IfFalse and last_cond_action_result is False
                if is_true or is_false:
                    for raw_action in value:
                        for action, subvalue in raw_action.items():
                            action = self._get_actions_enum(action)
                            try:
                                await process_action(action, subvalue)
                            except StopExecution:
                                return bool(last_expel_action)
    return bool(last_expel_action)

def accounts_register(
    request: HttpRequest,
    key: str = REQ(default=""),
    timezone: str = REQ(default="", converter=to_timezone_or_empty),
    from_confirmation: Optional[str] = REQ(default=None),
    form_full_name: Optional[str] = REQ("full_name", default=None),
    source_realm_id: Optional[int] = REQ(
        default=None, converter=to_converted_or_fallback(to_non_negative_int, None)
    ),
) -> HttpResponse:
    try:
        prereg_user = check_prereg_key(request, key)
    except ConfirmationKeyError as e:
        return render_confirmation_key_error(request, e)
    email = prereg_user.email
    realm_creation = prereg_user.realm_creation
    password_required = prereg_user.password_required
    role = prereg_user.invited_as
    if realm_creation:
        role = UserProfile.ROLE_REALM_OWNER
    try:
        validators.validate_email(email)
    except ValidationError:
        return render(request, "zerver/invalid_email.html", context={"invalid_email": True})
    if realm_creation:
        realm = None
    else:
        assert prereg_user.realm is not None
        if get_subdomain(request) != prereg_user.realm.string_id:
            return render_confirmation_key_error(
                request, ConfirmationKeyError(ConfirmationKeyError.DOES_NOT_EXIST)
            )
        realm = prereg_user.realm
        try:
            email_allowed_for_realm(email, realm)
        except DomainNotAllowedForRealmError:
            return render(
                request,
                "zerver/invalid_email.html",
                context={"realm_name": realm.name, "closed_domain": True},
            )
        except DisposableEmailError:
            return render(
                request,
                "zerver/invalid_email.html",
                context={"realm_name": realm.name, "disposable_emails_not_allowed": True},
            )
        except EmailContainsPlusError:
            return render(
                request,
                "zerver/invalid_email.html",
                context={"realm_name": realm.name, "email_contains_plus": True},
            )
        if realm.deactivated:
            return redirect_to_deactivation_notice()
        try:
            validate_email_not_already_in_realm(realm, email)
        except ValidationError:
            return redirect_to_email_login_url(email)
        if settings.BILLING_ENABLED:
            try:
                check_spare_licenses_available_for_registering_new_user(realm, email, role=role)
            except LicenseLimitError:
                return render(request, "zerver/no_spare_licenses.html")
    name_validated = False
    require_ldap_password = False
    if from_confirmation:
        try:
            del request.session["authenticated_full_name"]
        except KeyError:
            pass
        ldap_full_name = None
        if settings.POPULATE_PROFILE_VIA_LDAP:
            for backend in get_backends():
                if isinstance(backend, LDAPBackend):
                    try:
                        ldap_username = backend.django_to_ldap_username(email)
                    except NoMatchingLDAPUserError:
                        logging.warning("New account email %s could not be found in LDAP", email)
                        break
                    ldap_user = _LDAPUser(backend, ldap_username)
                    try:
                        ldap_full_name = backend.get_mapped_name(ldap_user)
                    except TypeError:
                        break
                    require_ldap_password = isinstance(backend, ZulipLDAPAuthBackend)
                    break
        if ldap_full_name:
            form = RegistrationForm({"full_name": ldap_full_name}, realm_creation=realm_creation)
            request.session["authenticated_full_name"] = ldap_full_name
            name_validated = True
        elif realm is not None and realm.is_zephyr_mirror_realm:
